CREATE DATABASE IF NOT EXISTS nexa_black CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nexa_black;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,cpf VARCHAR(14) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE accounts(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL UNIQUE,agency VARCHAR(10) NOT NULL,account_number VARCHAR(20) NOT NULL UNIQUE,balance DECIMAL(15,2) NOT NULL DEFAULT 0,credit_limit DECIMAL(15,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE transactions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,account_id INT UNSIGNED NOT NULL,type ENUM('income','expense') NOT NULL,category VARCHAR(40) NOT NULL DEFAULT 'other',description VARCHAR(180) NOT NULL,amount DECIMAL(15,2) NOT NULL,status ENUM('completed','pending','cancelled') NOT NULL DEFAULT 'completed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(account_id,created_at),FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE);
CREATE TABLE pix_keys(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,type ENUM('email','phone','cpf','random') NOT NULL,`key` VARCHAR(180) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cards(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,brand VARCHAR(30) NOT NULL DEFAULT 'Nexa Black',type ENUM('credit','debit') NOT NULL DEFAULT 'credit',last_four CHAR(4) NOT NULL,limit_amount DECIMAL(15,2) NOT NULL DEFAULT 0,available_amount DECIMAL(15,2) NOT NULL DEFAULT 0,due_day TINYINT UNSIGNED NOT NULL DEFAULT 10,status ENUM('active','blocked','cancelled') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE goals(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,target_amount DECIMAL(15,2) NOT NULL,current_amount DECIMAL(15,2) NOT NULL DEFAULT 0,deadline DATE NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
